Given a directed graph and two vertices src and dest, the task is to count all possible walks from vertex src to vertex dest that consist of exactly k edges.The graph is represented using an adjacency matrix adj[][], where adj[i][j] = 1 indicates the presence of a directed edge from vertex i to vertex j, and adj[i][j] = 0 indicates no edge from i to j.Example:Input: adj[][] = [[0, 1, 1, 1],                            [0, 0, 0, 1],                            [0, 0, 0, 1],                            [0, 0, 0, 0]]src = 0, dest = 3, k = 2Output: 2Explanation: There are two walks from src (0) to dest (3) with exactly 2 edges: (0 → 1 → 3) and (0 → 2 → 3).Try It YourselfTable of Content[Brute-Force Approach] Using Recursion - O(v^k) Time and O(k) Space[Expected Approach] Using Dynamic Programming - O(k*(v^3)) Time and O(k*(v^2)) Space[Brute-Force Approach] Using Recursion - O(v^k) Time and O(k) SpaceThe idea is to recursively explore all possible walks from src to dest using exactly k edges. The thought process is that from the current node, we try all its adjacent neighbors and reduce k by 1 in each recursive call. If k becomes 0, we check whether we’ve reached the destination — if yes, that’s a valid walk. 
            C++

    // C++ Code to count walks from src to dest
// with exactly k edges using recursion
#include <iostream>
#include <vector>
using namespace std;

// Function to count all walks from src to dest
// using exactly k edges
int countWalks(vector<vector<int>> &adj,
               int src, int dest, int k) {

    // Base Case: If k is 0 and src is same as dest
    if (k == 0 && src == dest) {
        return 1;
    }

    // If k is 0 and src is not dest, no walk possible
    if (k == 0) {
        return 0;
    }

    int count = 0;

    // Try all adjacent vertices from src
    for (int i = 0; i < adj.size(); i++) {

        // If there is an edge from src to i
        if (adj[src][i] == 1) {

            // Recur for the remaining k-1 edges
            count += countWalks(adj, i, dest, k - 1);
        }
    }

    return count;
}

int main() {

    vector<vector<int>> adj = {
        {0, 1, 1, 1},
        {0, 0, 0, 1},
        {0, 0, 0, 1},
        {0, 0, 0, 0}
    };

    int src = 0, dest = 3, k = 2;

    cout << countWalks(adj, src, dest, k);

    return 0;
}


